{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://bridge2ai.github.io/data-sheets-schema/evaluation/rubric10-semantic.schema.json",
  "title": "Rubric10-Semantic Evaluation Schema",
  "description": "Schema for D4D evaluation results using the Rubric10-Semantic framework with semantic validation (10 elements, 50 sub-elements)",
  "type": "object",
  "required": [
    "rubric",
    "version",
    "d4d_file",
    "project",
    "method",
    "evaluation_timestamp",
    "model",
    "overall_score",
    "elements",
    "semantic_analysis"
  ],
  "properties": {
    "rubric": {
      "type": "string",
      "const": "rubric10-semantic",
      "description": "Rubric type identifier"
    },
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+$",
      "description": "Rubric version (e.g., '1.0')"
    },
    "d4d_file": {
      "type": "string",
      "description": "Path to the D4D YAML file being evaluated"
    },
    "project": {
      "type": "string",
      "enum": [
        "AI_READI",
        "CHORUS",
        "CM4AI",
        "VOICE"
      ],
      "description": "Project name"
    },
    "method": {
      "type": "string",
      "enum": [
        "curated",
        "gpt5",
        "claudecode",
        "claudecode_agent",
        "claudecode_agent_core",
        "claudecode_api",
        "claudecode_api_core",
        "claudecode_assistant",
        "rocrate_mapped",
        "rocrate_static_map",
        "claudecode_agent_crate",
        "claudecode_agent_crate_core",
        "claudecode_agent_healthsheet",
        "claudecode_agent_healthsheet_core",
        "claudecode_agent_crate_only",
        "claudecode_agent_crate_only_core"
      ],
      "description": "Generation method. Mirrors data_sheets_schema.constants.METHODS; pinned by tests/test_evaluation/test_semantic_evaluation_contract.py"
    },
    "evaluation_timestamp": {
      "type": "string",
      "format": "date-time",
      "description": "ISO 8601 timestamp of evaluation"
    },
    "model": {
      "type": "object",
      "required": [
        "name",
        "temperature",
        "evaluation_type"
      ],
      "properties": {
        "name": {
          "type": "string",
          "description": "Model identifier (e.g., claude-sonnet-4-5-20250929)"
        },
        "temperature": {
          "type": [
            "number",
            "null"
          ],
          "minimum": 0.0,
          "maximum": 1.0,
          "description": "Actual runtime temperature, or null when the runtime does not expose it; a fixed temperature does not guarantee repeated scores."
        },
        "evaluation_type": {
          "type": "string",
          "enum": [
            "semantic_llm_judge",
            "llm_as_judge"
          ],
          "description": "Type of evaluation"
        }
      }
    },
    "overall_score": {
      "type": "object",
      "required": [
        "total_points",
        "max_points",
        "excluded_max_points",
        "adjusted_max_points",
        "normalized_percentage",
        "sub_elements_not_applicable"
      ],
      "properties": {
        "total_points": {
          "type": "integer",
          "minimum": 0,
          "description": "Points earned across applicable items"
        },
        "max_points": {
          "type": "integer",
          "const": 50,
          "description": "Maximum before N/A exclusions"
        },
        "excluded_max_points": {
          "type": "integer",
          "minimum": 0,
          "description": "Sum of max_score over items marked applicable: false"
        },
        "adjusted_max_points": {
          "type": "integer",
          "minimum": 0,
          "description": "max_points minus excluded_max_points"
        },
        "normalized_percentage": {
          "type": "number",
          "minimum": 0,
          "maximum": 100,
          "description": "total_points / adjusted_max_points x 100. Report alongside the fixed-base percentage and excluded items; different applicability does not establish comparability."
        },
        "sub_elements_not_applicable": {
          "type": "integer",
          "minimum": 0,
          "description": "Count of sub-elements marked applicable: false"
        },
        "fixed_percentage": {
          "type": "number",
          "minimum": 0,
          "maximum": 100,
          "description": "total_points / max_points x 100, before N/A exclusions. Required by the current agent instructions; optional here so preserved older evaluations remain readable."
        }
      }
    },
    "elements": {
      "type": "array",
      "minItems": 10,
      "maxItems": 10,
      "description": "Ten evaluation elements (each with 5 sub-elements)",
      "items": {
        "type": "object",
        "required": [
          "id",
          "name",
          "description",
          "sub_elements",
          "element_score",
          "element_max"
        ],
        "properties": {
          "id": {
            "type": "integer",
            "minimum": 1,
            "maximum": 10,
            "description": "Element number (1-10)"
          },
          "name": {
            "type": "string",
            "description": "Element name/title"
          },
          "description": {
            "type": "string",
            "description": "Element description/question"
          },
          "sub_elements": {
            "type": "array",
            "minItems": 5,
            "maxItems": 5,
            "description": "Five sub-elements per element (binary 0/1 scoring)",
            "items": {
              "type": "object",
              "required": [
                "name",
                "score",
                "evidence",
                "quality_note"
              ],
              "properties": {
                "name": {
                  "type": "string",
                  "description": "Sub-element name/criterion"
                },
                "score": {
                  "type": [
                    "integer",
                    "null"
                  ],
                  "enum": [
                    0,
                    1,
                    null
                  ],
                  "description": "Binary score: 1 met, 0 not met, null when the sub-element is not applicable. null is a different claim from 0, which says the sub-element was assessed and not met."
                },
                "evidence": {
                  "type": "string",
                  "description": "Evidence from D4D file supporting the score"
                },
                "quality_note": {
                  "type": "string",
                  "description": "Qualitative assessment and justification"
                },
                "semantic_validation": {
                  "type": "string",
                  "description": "Optional semantic validation notes (format checks, consistency)"
                }
              }
            }
          },
          "element_score": {
            "type": "integer",
            "minimum": 0,
            "maximum": 5,
            "description": "Sum of sub-element scores (0-5)"
          },
          "element_max": {
            "type": "integer",
            "minimum": 0,
            "maximum": 5,
            "description": "Points available for this element after N/A exclusions. Not a constant 5: the convention subtracts excluded sub-elements from the denominator, and records already carry element_max of 3."
          }
        }
      }
    },
    "semantic_analysis": {
      "type": "object",
      "required": [
        "issues_detected",
        "semantic_insights",
        "consistency_checks",
        "correctness_validations"
      ],
      "properties": {
        "issues_detected": {
          "type": "array",
          "description": "Semantic issues found during evaluation",
          "items": {
            "type": "object",
            "required": [
              "type",
              "severity",
              "description",
              "fields_involved",
              "recommendation"
            ],
            "properties": {
              "type": {
                "type": "string",
                "description": "Issue type (e.g. correctness, consistency, completeness, content_accuracy, semantic_understanding)"
              },
              "severity": {
                "type": "string",
                "enum": [
                  "low",
                  "medium",
                  "high"
                ],
                "description": "Issue severity"
              },
              "description": {
                "type": "string",
                "description": "Issue description"
              },
              "fields_involved": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "D4D fields involved"
              },
              "recommendation": {
                "type": "string",
                "description": "Recommendation for fixing"
              }
            }
          }
        },
        "semantic_insights": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Positive semantic observations"
        },
        "consistency_checks": {
          "type": "object",
          "required": [
            "passed",
            "failed",
            "warnings"
          ],
          "properties": {
            "passed": {
              "type": "integer",
              "minimum": 0,
              "description": "Number of consistency checks passed"
            },
            "failed": {
              "type": "integer",
              "minimum": 0,
              "description": "Number of consistency checks failed"
            },
            "warnings": {
              "type": "integer",
              "minimum": 0,
              "description": "Number of warnings issued"
            }
          }
        },
        "correctness_validations": {
          "type": "object",
          "description": "Format validation results (valid/invalid/not_applicable/not_present, may include specific validators like valid_nih, valid_zenodo)",
          "properties": {
            "doi_format": {
              "type": "string",
              "description": "DOI format validation (e.g., valid, valid_zenodo, invalid, not_applicable, not_present)"
            },
            "grant_number_format": {
              "type": "string",
              "description": "Grant number format validation (e.g., valid, valid_nih, invalid, not_applicable, not_present)"
            },
            "rrid_format": {
              "type": "string",
              "description": "RRID format validation (e.g., valid, invalid, not_applicable, not_present)"
            },
            "url_validity": {
              "type": "string",
              "description": "URL validation status (e.g., all_valid, some_invalid, not_applicable, not_present)"
            }
          },
          "additionalProperties": {
            "type": "string",
            "description": "Additional validation results"
          }
        }
      },
      "description": "Semantic validation and quality assessment"
    },
    "recommendations": {
      "type": "array",
      "description": "Actionable recommendations for improving the D4D datasheet",
      "items": {
        "type": "string"
      }
    },
    "evaluation_metadata": {
      "type": "object",
      "description": "Additional evaluation metadata (optional)",
      "properties": {
        "evaluator_id": {
          "type": "string",
          "description": "Unique evaluator identifier (optional)"
        },
        "rubric_hash": {
          "type": "string",
          "description": "SHA-256 hash of rubric file used (optional)"
        },
        "d4d_file_hash": {
          "type": "string",
          "description": "SHA-256 hash of D4D file evaluated (optional)"
        },
        "evaluation_duration_seconds": {
          "type": "number",
          "description": "Time taken to complete evaluation (optional)"
        }
      }
    }
  }
}
